=== Claim.java
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim made by a person on a sheet. Mutable so an Apply step changes it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private final long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private Integer number;
    private BigDecimal settledDue;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, Integer number, BigDecimal settledDue) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
    }

    public long getId() { return id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
    public LocalDate getDate() { return date; }
    public void setDate(LocalDate date) { this.date = date; }
    public String getNote() { return note; }
    public void setNote(String note) { this.note = note; }
    public ClaimStatus getStatus() { return status; }
    public void setStatus(ClaimStatus status) { this.status = status; }
    /** The claim's number on the sheet: null for a draft or a voided claim. */
    public Integer getNumber() { return number; }
    public void setNumber(Integer number) { this.number = number; }
    /** The due fixed when the claim was settled: null while it is live (not settled, or settled without a rate). */
    public BigDecimal getSettledDue() { return settledDue; }
    public void setSettledDue(BigDecimal settledDue) { this.settledDue = settledDue; }
}
=== ClaimAction.java
package net.officefloor.hq.app.claim;

import java.util.Set;

/** A status change, named as in the path: the statuses it may be taken from, the status it moves
 *  the claim to and the audit event it writes. */
public enum ClaimAction {
    OPEN(Set.of(ClaimStatus.DRAFT), ClaimStatus.OPEN, "CLAIM_OPENED"),
    SETTLE(Set.of(ClaimStatus.OPEN), ClaimStatus.SETTLED, "CLAIM_SETTLED"),
    VOID(Set.of(ClaimStatus.DRAFT, ClaimStatus.OPEN), ClaimStatus.VOID, "CLAIM_VOIDED");

    private final Set<ClaimStatus> from;
    private final ClaimStatus to;
    private final String event;

    ClaimAction(Set<ClaimStatus> from, ClaimStatus to, String event) {
        this.from = from;
        this.to = to;
        this.event = event;
    }

    public boolean allowedFrom(ClaimStatus status) { return from.contains(status); }
    public ClaimStatus to() { return to; }
    public String event() { return event; }
}
=== ApplyClaimAction.java
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Moves the claim to the action's status, refusing a change its current status does not allow.
 *  Opening gives the claim the sheet's next number; voiding clears it. Settling fixes the claim's
 *  due at the person's grade's rate in force on the claim's date (none when there is none, so it stays live).
 *  Publishes the number the audit line carries (for a void, the number the claim had). */
public class ApplyClaimAction {
    public void apply(@Val ClaimAction action, @Val Claim claim, ClaimRepository repository,
            PersonRepository people, RateRepository rates, Out<ClaimNumber> numberOut)
            throws InvalidClaimStatusException {
        if (!action.allowedFrom(claim.getStatus())) {
            throw new InvalidClaimStatusException(
                    "A " + claim.getStatus() + " claim cannot be moved to " + action.to() + ".");
        }
        Integer had = claim.getNumber();
        claim.setStatus(action.to());
        switch (action) {
            case OPEN -> claim.setNumber(repository.nextNumber(claim.getSheetId()));
            case VOID -> claim.setNumber(null);
            case SETTLE -> claim.setSettledDue(dueNow(claim, people, rates));
            default -> { }
        }
        numberOut.set(new ClaimNumber(action == ClaimAction.VOID ? had : claim.getNumber()));
    }

    /** amount × pct / 100, rounded half to even to two decimals; null when no rate is in force on the claim's date. */
    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates) {
        Person person = people.findById(claim.getSheetId(), claim.getPersonId());
        return Rate.inForce(rates.findBySheet(claim.getSheetId()), person.getGrade(), claim.getDate())
                .map(r -> claim.getAmount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }
}
